<template><section><h3>Invoices for the responsible billing party</h3><p>Preview the selected external billing contact and the amount before sending a private payment link. Each invoice permits payment only.</p><button type="button" :disabled="loading" @click="load">Refresh payable balances</button><p v-if="error" role="alert">{{error}}</p><p v-if="loading" role="status">Checking balances…</p><p v-else-if="!balances.length">No verified unpaid balances are ready for an invoice.</p><article v-for="balance in balances" :key="balance.allocationId"><strong>{{money(balance.amountCents,balance.currency)}}</strong><GuestInvoiceShare :agency-id="agencyId" :allocation-id="balance.allocationId" :amount-cents="balance.amountCents" :currency="balance.currency" external-responsible /></article></section></template>
<script setup>
import {onBeforeUnmount,ref,watch} from 'vue';import api from '../../services/api';import GuestInvoiceShare from './GuestInvoiceShare.vue';
const props=defineProps({agencyId:[String,Number],clientId:[String,Number]});const balances=ref([]),loading=ref(false),error=ref('');let generation=0;
const money=(value,currency)=>new Intl.NumberFormat('en-US',{style:'currency',currency:currency||'USD'}).format(value/100);
async function load(){const version=++generation;balances.value=[];loading.value=true;error.value='';try{const{data}=await api.get(`/family-billing/account/clients/${props.clientId}/guest-invoice-balances`,{params:{agencyId:props.agencyId},skipGlobalLoading:true});if(version===generation)balances.value=data.balances;}catch(e){if(version===generation)error.value=e.response?.data?.error?.message||'Payable balances could not be loaded.';}finally{if(version===generation)loading.value=false;}}
watch(()=>[props.agencyId,props.clientId],load,{immediate:true});onBeforeUnmount(()=>{generation++;});
</script>
<style scoped>section{margin:20px 0;padding:18px;border:1px solid #d5e1ed;border-radius:10px}article{padding:14px 0;border-top:1px solid #e4e9ef}button{padding:9px 12px;cursor:pointer}[role=alert]{color:#a11}</style>
